 return pageHead("FARMER SETTLEMENT","ખેડૂત ચુકવણી અને ખાતું","ખેડૂતને ચૂકવવાપાત્ર, ચૂકવેલ, બાકી રકમ, payment reference અને due date bill-wise track કરો.",'<button class="btn" data-action="export-payments"><svg><use href="#i-download"/></svg>Export CSV</button>')+
 '<div class="stats-grid">'+stat("કુલ ખેડૂત payable",money(data.bills.reduce((s,b)=>s+b.net,0)),"બધા sale bills","receipt")+stat("ખેડૂતને ચૂકવેલ",money(paid),"Payment record","check")+stat("ખેડૂતનું બાકી",money(due),"બાકી bill balance","wallet","amber")+stat("મર્યાદા વટાવેલ",data.bills.filter(b=>b.net>(b.paid||0)&&overdue(b.farmerPaymentDueAt)).length+" bill","Payment deadline crossed","alert","red")+'</div>'+
 tableShell("ખેડૂત ચુકવણી રજિસ્ટર","Farmer payable / paid / balance અને હરાજી slipમાંથી auto-generated payment deadline",'<table><thead><tr><th>Bill / Lot</th><th>ખેડૂત / ID</th><th>ચૂકવવાપાત્ર</th><th>ચૂકવેલ</th><th>બાકી</th><th>ચુકવણી deadline</th><th>સ્થિતિ</th><th></th></tr></thead><tbody>'+rows+'</tbody></table>')+
 tableShell("Buyer-side market fee / અન્ય dues","ખેડૂતના payableથી અલગ buyer-side fees; કોઈ રકમ લાગુ કરવી હોય તો APMC-approved configuration મુજબ",'<table><thead><tr><th>Bill / Lot</th><th>ખરીદદાર</th><th>Market fee</th><th>અન્ય dues</th><th>કુલ dues</th><th>ચૂકવેલ</th><th>બાકી</th><th></th></tr></thead><tbody>'+data.bills.filter(b=>(b.buyerTotalDue||0)>0).map(b=>'<tr><td>'+b.billNo+'<span class="cell-sub">'+b.lotId+'</span></td><td>'+esc(b.buyer)+'</td><td>'+money(b.buyerMarketFee||0)+'</td><td>'+money(b.buyerOther||0)+'</td><td>'+money(b.buyerTotalDue||0)+'</td><td>'+money(b.buyerFeePaid||0)+'</td><td>'+money((b.buyerTotalDue||0)-(b.buyerFeePaid||0))+'</td><td>'+((b.buyerTotalDue||0)>(b.buyerFeePaid||0)?rowAction("Buyer dues નોંધો","record-buyer-fee",b.billNo):statusChip("paid"))+'</td></tr>').join("")||noRows("આ demoમાં buyer-side fee/dues record નથી.")+'</tbody></table>')+
 '<div class="notice" style="margin-top:13px">આ screen ખેડૂતને ચૂકવવાની રકમ બતાવે છે. વેપારી પાસેથી ખરીદ રકમ વસૂલવાની અલગ ledger માટે “વેપારી ખાતું / Credit” ખોલો. Demoમાં payment entry માત્ર નોંધ છે; real bank transfer થતો નથી.</div>';
