function renderBuyerLedger(){
 const balances=data.buyers.map(name=>{
  const profile=buyerProfile(name),bills=data.bills.filter(b=>b.buyer===name),activeLots=data.lots.filter(l=>l.buyer===name&&l.ticketNo&&!billByLot(l.id)&&l.status!=="dispatched"),paid=bills.reduce((s,b)=>s+Number(b.buyerPurchasePaid||0),0),billDue=bills.reduce((s,b)=>s+Math.max(0,Number(b.gross||0)-Number(b.buyerPurchasePaid||0)),0),activeExposure=activeLots.reduce((s,l)=>s+Number(l.provisional||l.rate*(l.net||l.estimated||0)||0),0),due=billDue+activeExposure,overdueBills=bills.filter(b=>Number(b.gross||0)>Number(b.buyerPurchasePaid||0)&&overdue(b.buyerCreditDueAt)).length+activeLots.filter(l=>overdue(l.buyerCreditDueAt)).length,limit=Number(profile.purchaseLimit||0),limitFull=limit>0&&due>=limit;
  return {name,profile,paid,due,overdueBills,limit,limitFull};
 });
 const rows=balances.map(x=>'<tr><td><span class="cell-title">'+esc(x.name)+'</span></td><td>'+esc(x.profile.registrationNo||"Registration ID બાકી")+'</td><td>'+x.profile.creditDays+' દિવસ</td><td>'+ (x.limit?money(x.limit):"Open / not set")+'</td><td>'+money(x.paid)+'</td><td><strong>'+money(x.due)+'</strong></td><td>'+(x.overdueBills?'<span class="status danger">'+x.overdueBills+' overdue</span>':x.limitFull?'<span class="status warning">Limit full</span>':'<span class="status success">Within limit</span>')+'</td><td>'+rowAction("Edit","edit-buyer",x.name)+'</td></tr>').join("")||noRows("વેપારી ઉમેરો");
 const billDueRows=data.bills.filter(b=>Number(b.gross||0)>Number(b.buyerPurchasePaid||0)).map(b=>'<tr><td>'+b.billNo+'<span class="cell-sub">'+b.lotId+'</span></td><td>'+esc(b.buyer)+'</td><td>'+money(b.gross||0)+'</td><td>'+money(b.buyerPurchasePaid||0)+'</td><td><strong>'+money(Math.max(0,b.gross-(b.buyerPurchasePaid||0)))+'</strong></td><td>'+fmtDeadline(b.buyerCreditDueAt)+'<span class="cell-sub">'+remainingLabel(b.buyerCreditDueAt)+'</span></td><td>'+statusChip(overdue(b.buyerCreditDueAt)?"payment_pending":"open")+'</td><td>'+rowAction("ચુકવણી નોંધો","record-buyer-purchase-payment",b.billNo)+'</td></tr>').join("");
 const activeDueRows=data.lots.filter(l=>l.buyer&&l.ticketNo&&!billByLot(l.id)&&l.status!=="dispatched").map(l=>'<tr><td>Ticket '+esc(l.ticketNo)+'<span class="cell-sub">'+l.id+' · bill pending</span></td><td>'+esc(l.buyer)+'</td><td>'+money(l.provisional||0)+'<span class="cell-sub">પ્રાથમિક હરાજી value</span></td><td>—</td><td><strong>'+money(l.provisional||0)+'</strong></td><td>'+fmtDeadline(l.buyerCreditDueAt)+'<span class="cell-sub">'+remainingLabel(l.buyerCreditDueAt)+'</span></td><td>'+statusChip(overdue(l.buyerCreditDueAt)?"payment_pending":"open")+'</td><td>તોલ / બિલ બાકી</td></tr>').join("");
 const dueRows=billDueRows+activeDueRows||'<tr><td colspan="8">વેપારીની ખરીદ ચુકવણી બાકી નથી.</td></tr>';
 const totalDue=balances.reduce((s,x)=>s+x.due,0),totalPaid=balances.reduce((s,x)=>s+x.paid,0),blocked=balances.filter(x=>x.overdueBills||x.limitFull).length;
 return pageHead("TRADER ACCOUNT & CREDIT CONTROL","વેપારી ખાતું અને ખરીદ મર્યાદા","દરેક વેપારીનું Registration ID, credit days, purchase limit, ચુકવેલ ખરીદ રકમ અને outstanding એક જ જગ્યાએ.",'<button class="btn" data-action="add-buyer">+ નવો વેપારી</button>')+
 '<div class="stats-grid">'+stat("વેપારીઓ",data.buyers.length,"Master records","wallet")+stat("ખરીદ રકમ પ્રાપ્ત",money(totalPaid),"Buyer payments","check")+stat("વેપારી પાસેથી બાકી",money(totalDue),"Outstanding purchase balance","receipt","amber")+stat("Credit hold",blocked+" વેપારી","Overdue / limit full","alert",blocked?"red":"")+'</div>'+
 '<div class="notice warn" style="margin-bottom:14px">Credit days દરેક વેપારી માટે અલગ છે. Credit deadline વટે અથવા configured purchase limit પૂરી થાય તો નવી હરાજીમાં તે વેપારીને પસંદ કરવા નહીં દઈએ. Actual block / grace / release policy APMCની મંજૂરીથી નક્કી કરવી.</div>'+
 tableShell("વેપારી માસ્ટર અને Credit Policy","Registration / licence reference, કેટલા દિવસની ખરીદ મર્યાદા અને મંજૂર purchase exposure",'<table><thead><tr><th>વેપારી</th><th>Registration / Licence ID</th><th>Credit days</th><th>Purchase limit</th><th>ચૂકવેલ</th><th>બાકી ખરીદ</th><th>Credit સ્થિતિ</th><th></th></tr></thead><tbody>'+rows+'</tbody></table>')+
 '<div style="height:14px"></div>'+tableShell("વેપારીની Bill-wise ખરીદ ચુકવણી","હરાજી પછી વેપારીએ કેટલું ચૂકવ્યું અને કેટલું બાકી છે",'<table><thead><tr><th>Bill / Lot</th><th>વેપારી</th><th>ખરીદ કિંમત</th><th>ચૂકવેલ</th><th>બાકી</th><th>Credit due date</th><th>Status</th><th></th></tr></thead><tbody>'+dueRows+'</tbody></table>')+
 '<div class="notice" style="margin-top:13px">આ ખરીદ રકમનો ledger market fee / અન્ય duesથી અલગ છે. Actual accountingમાં ખરીદદાર પાસેથી પ્રાપ્ત રકમ, ખેડૂતને ચુકવણી, commission, fee અને settlement mapping APMCની approved accounting policy પ્રમાણે અલગ રાખવી.</div>';
}
