   if(Number(p.purchaseLimit||0)>0&&outstanding+newExposure>Number(p.purchaseLimit)){toast("આ હરાજીથી વેપારીની મંજૂર purchase limit વટાશે.","error",v.buyer);return;}
   const createdAt=new Date(),buyerDays=Math.max(0,Number(p.creditDays||data.terms.defaultBuyerCreditDays||0));
