   if(!existing){const t=ticketByLot(l.id);existing={billNo:"SB-26-"+String(data.nextBill++).padStart(5,"0"),lotId:l.id,farmer:l.farmer,buyer:l.buyer,weight:l.net,rate,gross:grossAmt,deductions:sellerDeduction,sellerDeductions:sellerDeduction,buyerMarketFee,buyerOther,buyerTotalDue:buyerMarketFee+buyerOther,buyerFeePaid:0,buyerFeeStatus:(buyerMarketFee+buyerOther)>0?"payment_pending":"paid",buyerPurchasePaid:0,buyerRegistrationNo:t?.buyerRegistrationNo||buyerProfile(l.buyer).registrationNo||"",buyerCreditDays:t?.buyerCreditDays||buyerProfile(l.buyer).creditDays,buyerCreditDueAt:t?.buyerCreditDueAt||l.buyerCreditDueAt,farmerPaymentDueAt:t?.farmerPaymentDueAt||l.farmerPaymentDueAt,dispatchDueAt:t?.dispatchDueAt||l.dispatchDueAt,net:Math.max(0,grossAmt-sellerDeduction),status:"payment_pending",paid:0};data.bills.unshift(existing);l.billNo=existing.billNo;}
